<?php require_once 'bootstrap.php';$u=require_admin();$scope=user_club_sic($u['sic_id']);if(!acl_can($u['sic_id'],'project','READ',$scope,$u['sic_id'])&&!has_role($u['sic_id'],'SUPERADMIN')){http_response_code(403);exit('Accesso non autorizzato.');}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$act=$_POST['act']??'';$sic=$_POST['sic']??'';if($act==='verify_volunteer'){$st=db()->prepare('SELECT * FROM volunteer_actions WHERE sic_id=?');$st->execute([$sic]);$v=$st->fetch();if($v&&!$v['verified']){$reward=(int)round((float)$v['hours']*25);db()->prepare('UPDATE volunteer_actions SET verified=1,drx_awarded=? WHERE sic_id=?')->execute([$reward,$sic]);drx_post($v['user_sic_id'],null,$reward,'VOLUNTEERING',true,'volunteer:'.$sic,$sic,['hours'=>$v['hours']]);$msg='Volontariato verificato.';}}elseif($act==='confirm_donation'){db()->prepare("UPDATE donations SET status='CONFIRMED',payment_reference=? WHERE sic_id=?")->execute([trim($_POST['reference']??''),$sic]);$msg='Pagamento donazione confermato in tesoreria.';}}$vol=db()->query("SELECT v.*,u.display_name,p.title project_title FROM volunteer_actions v LEFT JOIN users u ON u.sic_id=v.user_sic_id LEFT JOIN projects p ON p.sic_id=v.project_sic_id WHERE v.verified=0 ORDER BY v.created_at")->fetchAll();$don=db()->query("SELECT d.*,u.display_name,p.title project_title FROM donations d LEFT JOIN users u ON u.sic_id=d.donor_user_sic_id LEFT JOIN projects p ON p.sic_id=d.project_sic_id WHERE d.status='PLEDGED' ORDER BY d.created_at")->fetchAll();$pageTitle='Social Impact Admin';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Verification</span><h1>Social Impact Admin</h1><p>Solo azioni verificate generano DRX. Una promessa di donazione non è contabilizzata come pagamento finché non viene confermata.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="card"><h2>Volontariato da verificare</h2><?php foreach($vol as $v):?><article class="course"><h3><?=h($v['display_name'])?> · <?=h($v['project_title'])?></h3><p><?=h((string)$v['hours'])?> ore · <?=h($v['description'])?></p><form method="post"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="act" value="verify_volunteer"><input type="hidden" name="sic" value="<?=h($v['sic_id'])?>"><button class="btn primary small">Verifica e assegna DRX</button></form></article><?php endforeach;?></section><section class="card"><h2>Donazioni da confermare</h2><?php foreach($don as $d):?><article class="course"><h3><?=h($d['display_name']?:'Anonimo')?> · € <?=number_format((float)$d['amount_eur'],2,',','.')?></h3><p><?=h($d['project_title'])?></p><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="act" value="confirm_donation"><input type="hidden" name="sic" value="<?=h($d['sic_id'])?>"><input name="reference" placeholder="Riferimento pagamento"><button class="btn small">Conferma pagamento</button></form></article><?php endforeach;?></section><?php require '_footer.php';?>